const PptxGenJS = require('pptxgenjs');
const pres = new PptxGenJS();

pres.layout = 'LAYOUT_WIDE'; // 13.33 x 7.5 inches

// Color palette
const COLORS = {
  primary: '2B579A',    // Deep blue
  accent: '4CAF50',     // Green
  dark: '333333',
  light: 'F5F5F5',
  white: 'FFFFFF',
  subtitle: '666666'
};

// ========== Slide 1: Title ==========
const slide1 = pres.addSlide();
slide1.background = { color: COLORS.primary };
slide1.addText('团队协作', {
  x: 1, y: 1.8, w: 11.33, h: 1.5,
  fontSize: 48, bold: true, color: COLORS.white, align: 'center', fontFace: '微软雅黑'
});
slide1.addText('打造高效协同的团队文化', {
  x: 1, y: 3.5, w: 11.33, h: 0.8,
  fontSize: 24, color: 'D0E0FF', align: 'center', fontFace: '微软雅黑'
});
slide1.addShape(pres.ShapeType.rect, {
  x: 4.5, y: 4.6, w: 4.33, h: 0.04, fill: { color: COLORS.accent }
});
slide1.addText('2024 · 团队管理系列', {
  x: 1, y: 5.2, w: 11.33, h: 0.6,
  fontSize: 16, color: 'AABBDD', align: 'center', fontFace: '微软雅黑'
});

// ========== Slide 2: Why Team Collaboration Matters ==========
const slide2 = pres.addSlide();
slide2.background = { color: COLORS.white };
slide2.addText('为什么团队协作至关重要？', {
  x: 0.8, y: 0.4, w: 11.73, h: 0.9,
  fontSize: 32, bold: true, color: COLORS.primary, fontFace: '微软雅黑'
});
slide2.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.3, w: 2, h: 0.05, fill: { color: COLORS.accent }
});

const points2 = [
  { title: '提升效率', desc: '分工协作减少重复劳动，缩短项目交付周期' },
  { title: '激发创新', desc: '多元视角碰撞产生创意，避免思维盲区' },
  { title: '增强韧性', desc: '互相补位降低单点风险，应对突发变化更从容' },
  { title: '促进成长', desc: '知识共享与反馈循环加速个人与组织进化' }
];

points2.forEach((p, i) => {
  const yPos = 1.8 + i * 1.3;
  slide2.addShape(pres.ShapeType.roundRect, {
    x: 0.8, y: yPos, w: 0.6, h: 0.6,
    fill: { color: COLORS.primary }, rectRadius: 0.1
  });
  slide2.addText(String(i + 1), {
    x: 0.8, y: yPos, w: 0.6, h: 0.6,
    fontSize: 20, bold: true, color: COLORS.white, align: 'center', valign: 'middle', fontFace: '微软雅黑'
  });
  slide2.addText(p.title, {
    x: 1.7, y: yPos - 0.05, w: 4, h: 0.4,
    fontSize: 20, bold: true, color: COLORS.dark, fontFace: '微软雅黑'
  });
  slide2.addText(p.desc, {
    x: 1.7, y: yPos + 0.35, w: 10, h: 0.4,
    fontSize: 16, color: COLORS.subtitle, fontFace: '微软雅黑'
  });
});

// ========== Slide 3: Key Elements of Effective Collaboration ==========
const slide3 = pres.addSlide();
slide3.background = { color: COLORS.white };
slide3.addText('高效协作的四大支柱', {
  x: 0.8, y: 0.4, w: 11.73, h: 0.9,
  fontSize: 32, bold: true, color: COLORS.primary, fontFace: '微软雅黑'
});
slide3.addShape(pres.ShapeType.rect, {
  x: 0.8, y: 1.3, w: 2, h: 0.05, fill: { color: COLORS.accent }
});

const pillars = [
  { title: '清晰目标', icon: '🎯', items: ['共同愿景对齐', '可衡量的里程碑', '角色与责任明确'] },
  { title: '开放沟通', icon: '💬', items: ['信息透明及时', '积极倾听反馈', '心理安全感'] },
  { title: '信任尊重', icon: '🤝', items: ['信守承诺', '包容多元观点', '公平认可贡献'] },
  { title: '流程工具', icon: '⚙️', items: ['标准化工作流', '合适的协作平台', '定期复盘迭代'] }
];

pillars.forEach((p, i) => {
  const xPos = 0.5 + i * 3.15;
  // Card background
  slide3.addShape(pres.ShapeType.roundRect, {
    x: xPos, y: 1.7, w: 2.9, h: 5.2,
    fill: { color: COLORS.light }, rectRadius: 0.15, line: { color: 'E0E0E0', width: 1 }
  });
  // Icon
  slide3.addText(p.icon, {
    x: xPos, y: 1.9, w: 2.9, h: 0.8,
    fontSize: 36, align: 'center', valign: 'middle'
  });
  // Title
  slide3.addText(p.title, {
    x: xPos, y: 2.7, w: 2.9, h: 0.6,
    fontSize: 20, bold: true, color: COLORS.primary, align: 'center', fontFace: '微软雅黑'
  });
  // Separator
  slide3.addShape(pres.ShapeType.rect, {
    x: xPos + 0.7, y: 3.35, w: 1.5, h: 0.03, fill: { color: COLORS.accent }
  });
  // Items
  p.items.forEach((item, j) => {
    slide3.addText('• ' + item, {
      x: xPos + 0.3, y: 3.6 + j * 0.7, w: 2.4, h: 0.6,
      fontSize: 14, color: COLORS.dark, fontFace: '微软雅黑', valign: 'top'
    });
  });
});

// ========== Slide 4: Common Pitfalls & Solutions ==========
const slide4 = pres.addSlide();
slide4.background = { color: COLORS.white };
